// Thuế GTGT đầu ra (bán hàng) trừ đầu vào (mua hàng) trong tháng — số dương là ước tính
// phải nộp thêm, số âm là được khấu trừ/kết chuyển. CHỈ tham khảo nhanh, không thay thế tờ
// khai thuế thật (còn phụ thuộc hoá đơn đã nhận đủ hay chưa — xem workflow "Nhắc NCC chưa
// nhận hoá đơn"). Luôn gửi kể cả 0đ — kế toán vẫn cần biết tháng này không phát sinh gì.
const d = $json;
const vnd = n => new Intl.NumberFormat('vi-VN').format(n || 0) + '₫';
const payableLabel = d.vat_payable >= 0 ? 'Ước tính phải nộp thêm' : 'Ước tính được khấu trừ/kết chuyển';

const html = `<h2>🧮 Tổng hợp thuế GTGT — ${d.period_label}</h2>`
  + `<table border="1" cellpadding="6" cellspacing="0" style="border-collapse:collapse">`
  + `<tr><td>Doanh thu bán hàng</td><td align="right">${vnd(d.revenue)}</td></tr>`
  + `<tr><td>Thuế GTGT đầu ra</td><td align="right">${vnd(d.vat_output)}</td></tr>`
  + `<tr><td>Chi mua hàng</td><td align="right">${vnd(d.spend)}</td></tr>`
  + `<tr><td>Thuế GTGT đầu vào</td><td align="right">${vnd(d.vat_input)}</td></tr>`
  + `<tr><td><b>${payableLabel}</b></td><td align="right"><b>${vnd(Math.abs(d.vat_payable))}</b></td></tr>`
  + `</table>`
  + `<p style="color:#888;font-size:12px">${d.company_name} — ${new Date().toLocaleString('vi-VN', { timeZone: 'Asia/Ho_Chi_Minh' })}</p>`;

return { json: {
  email_to: d.company_email || '',
  email_subject: `🧮 Tổng hợp thuế GTGT ${d.period_label} — ${payableLabel.toLowerCase()} ${vnd(Math.abs(d.vat_payable))}`,
  email_html: html
} };
